<?php require_once __DIR__.'/../includes/auth.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=$pdo->prepare('SELECT s.*,u.full_name FROM sales s LEFT JOIN users u ON u.id=s.user_id WHERE s.id=?');$st->execute([$id]);$sale=$st->fetch();if(!$sale){flash('error','Sale not found.');redirect('index.php');}$st=$pdo->prepare('SELECT si.*,p.name,p.sku FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?');$st->execute([$id]);$items=$st->fetchAll();$pageTitle='Sale details';$base='/shop-inventory-management';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Sale details</h1><p>Invoice <?=e($sale['invoice_no'])?></p></div><div><a class="btn" href="index.php">← Sales history</a> <a class="btn primary" target="_blank" href="invoice.php?id=<?=$id?>">Print invoice</a></div></div><div class="panel"><div class="invoice-meta"><div><small>Invoice number</small><strong><?=e($sale['invoice_no'])?></strong></div><div><small>Date</small><strong><?=e($sale['created_at'])?></strong></div><div><small>Recorded by</small><strong><?=e($sale['full_name']??'Admin')?></strong></div><div><small>Status</small><strong><span class="badge success"><?=e(ucfirst($sale['status']))?></span></strong></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Unit price</th><th>Quantity</th><th>Line total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['sku'])?></td><td><?=money($i['unit_price'])?></td><td><?=$i['quantity']?></td><td><?=money($i['line_total'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="4" class="align-right">Subtotal</th><th><?=money($sale['subtotal'])?></th></tr><tr><th colspan="4" class="align-right">Grand total</th><th><?=money($sale['grand_total'])?></th></tr></tfoot></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
